(function(root){
const enc=new TextEncoder();
function pdf(images,s){const chunks=[],offset=[0];let len=0;const add=x=>{const a=typeof x==='string'?enc.encode(x):x;chunks.push(a);len+=a.length;};const obj=(n,body)=>{offset[n]=len;add(n+' 0 obj\n');add(body);add('\nendobj\n')};const factor=s.unit==='mm'?72/25.4:72/96,pw=s.width*factor,ph=s.height*factor;add('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,`<< /Type /Pages /Count ${images.length} /Kids [${images.map((_,i)=>(3+i*3)+' 0 R').join(' ')}] >>`);images.forEach((im,i)=>{const n=3+i*3,draw=`q ${pw} 0 0 ${ph} 0 0 cm /Im0 Do Q`;obj(n,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw} ${ph}] /Resources << /XObject << /Im0 ${n+1} 0 R >> >> /Contents ${n+2} 0 R >>`);offset[n+1]=len;add(`${n+1} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${im.width} /Height ${im.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${im.bytes.length} >>\nstream\n`);add(im.bytes);add('\nendstream\nendobj\n');obj(n+2,`<< /Length ${enc.encode(draw).length} >>\nstream\n${draw}\nendstream`)});const xref=len,count=3+images.length*3;add(`xref\n0 ${count}\n0000000000 65535 f \n`);for(let i=1;i<count;i++)add(String(offset[i]).padStart(10,'0')+' 00000 n \n');add(`trailer\n<< /Size ${count} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);return new Blob(chunks,{type:'application/pdf'});}
async function raster(s,page,type){const {width,height}=MenuModel.size(s);if(width*height>22000000)throw Error('预览版单页限 2200 万像素，请减小规格或 DPI');const blob=new Blob([MenuRenderer.svg(s,page)],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob);try{const im=new Image();await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=()=>reject(Error('图片渲染失败，请重新上传素材'));im.src=url});const cv=document.createElement('canvas');cv.width=width;cv.height=height;const cx=cv.getContext('2d');cx.fillStyle='#fff';cx.fillRect(0,0,width,height);cx.drawImage(im,0,0,width,height);const data=await new Promise(resolve=>cv.toBlob(resolve,type,.94));if(!data)throw Error('浏览器无法生成图片');return {blob:data,width,height,bytes:new Uint8Array(await data.arrayBuffer())};}finally{URL.revokeObjectURL(url)}}
async function build(s,onProgress=()=>{}){const all=MenuModel.pages(s),pages=s.range==='current'?[all[s.page]]:all,results=[],images=[],base=s.filename.trim();if(!base||/[\\/:*?"<>|]/.test(base))throw Error('文件名不能为空，且不能包含 \\ / : * ? " < > |');for(let i=0;i<pages.length;i++){const im=await raster(s,pages[i],s.format==='png'?'image/png':'image/jpeg');images.push(im);results.push({blob:im.blob,name:`${base}-${String(all.indexOf(pages[i])+1).padStart(2,'0')}.${s.format}`,pageId:pages[i].id});onProgress(Math.round((i+1)/pages.length*90));}if(s.format==='pdf')return [{name:base+'.pdf',blob:pdf(images,s)}];if(results.length===1)return results;if(!root.JSZip)throw Error('ZIP 组件未加载，请使用本地预览服务打开');const zip=new JSZip(),date=new Date(s.updatedAt);for(const r of results)zip.file(r.name,r.blob,{date});zip.file('export-manifest.json',JSON.stringify({prototype:true,projectVersion:s.revision,profile:{width:s.width,height:s.height,unit:s.unit},pages:results.map(r=>({id:r.pageId,file:r.name}))},null,2),{date});return [{name:base+'.zip',blob:await zip.generateAsync({type:'blob',compression:'DEFLATE'})}];}
async function publish(results){
  if(!['localhost','127.0.0.1'].includes(location.hostname))return results.map(f=>({...f,url:URL.createObjectURL(f.blob)}));
  const output=[];
  for(const f of results){const response=await fetch('/menu-design/exports',{method:'POST',headers:{'Content-Type':f.blob.type||'application/octet-stream','X-Menu-Filename':encodeURIComponent(f.name)},body:f.blob});if(response.status===404)return results.map(f=>({...f,url:URL.createObjectURL(f.blob)}));if(!response.ok)throw Error('本机下载服务不可用，请重试或检查服务');const {url}=await response.json();output.push({...f,url});}
  return output;
}
root.MenuExport={build,raster,pdf,publish};
})(window);
